import{_ as s,o as r,c as a,a2 as n}from"./chunks/framework.BXzK3EA4.js";const p="/assets/%E6%9F%A5%E7%9C%8B%E6%9F%90%E4%B8%80%E6%AC%BE%E4%BA%A7%E5%93%81%E8%AF%A6%E6%83%85.BXANH_RH.png",o="/assets/%E6%9F%A5%E7%9C%8B%E7%9B%AE%E6%A0%87%E6%9C%8D%E5%8A%A1%E5%99%A8%E8%AF%A6%E6%83%85.DJdsiPcA.png",e="/assets/%E7%AE%A1%E7%90%86%E4%BA%A7%E5%93%81.nRvqQl1J.png",i="/assets/%E4%BA%A7%E5%93%81%E6%88%96%E6%9C%8D%E5%8A%A1%E6%96%B0%E5%BC%80%E5%B7%A5%E5%8D%95.BQ40VCeT.png",l="/assets/%E6%96%B0%E5%BC%80%E5%B7%A5%E5%8D%9511.Bm6y4gmz.png",g="/assets/%E4%BA%A7%E5%93%81%E6%88%96%E6%9C%8D%E5%8A%A1%E7%9A%84%E8%B4%A6%E5%8D%95%E4%BF%A1%E6%81%AF.B-zEFmYy.png",E="/assets/%E6%96%B0%E6%88%91%E7%9A%84%E5%B8%90%E5%8D%95.CPjgmtVm.png",c="/assets/%E6%9F%A5%E7%9C%8B%E6%88%91%E7%9A%84%E6%9C%8D%E5%8A%A1%E8%AF%A6%E6%83%85.BGtPHtq7.png",m="/assets/%E6%9F%A5%E7%9C%8B%E8%B4%A6%E5%8D%95%E8%AF%A6%E6%83%85.AvWXT2sC.png",A="/assets/%E6%8F%90%E5%89%8D%E7%BB%AD%E8%B4%B9.DodGfwBu.png",_="/assets/%E4%BB%98%E6%AC%BE%E7%BB%93%E7%AE%97.D0WZRkKe.png",q=JSON.parse('{"title":"产品管理","description":"","frontmatter":{"title":"产品管理"},"headers":[],"relativePath":"beginners-guide/manage-products/product-management.md","filePath":"beginners-guide/manage-products/product-management.md","lastUpdated":1788259091000}'),d={name:"beginners-guide/manage-products/product-management.md"};function B(h,t,u,b,C,f){return r(),a("div",null,[...t[0]||(t[0]=[n('<p>产品管理支持管理已购买的物理服务器、裸机云和 VPS 等产品。</p><hr><h3 id="产品管理入口" tabindex="-1">产品管理入口 <a class="header-anchor" href="#产品管理入口" aria-label="Permalink to &quot;产品管理入口&quot;">​</a></h3><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在控制台左侧导航<strong>产品管理</strong>区域，单击目标产品或服务名称，进入<strong>我的产品与服务</strong>页面。 <strong>我的产品与服务</strong>页面支持查看产品/服务详情、新开工单、查看账单和提前续费等功能。</p><p><img src="'+p+'" alt="查看某一款产品详情.png"></p></li></ol><hr><h3 id="查看产品或服务详情" tabindex="-1">查看产品或服务详情 <a class="header-anchor" href="#查看产品或服务详情" aria-label="Permalink to &quot;查看产品或服务详情&quot;">​</a></h3><p>查看产品/服务详情支持查看不同地区和状态的产品/服务。</p><ol><li><p>在我的产品与服务页面，选择地区和状态，筛选出对应的产品/服务。状态是指产品/服务的使用状态，包括全部、有效的、审核中、已暂停、已终止和已取消。</p><p><img src="'+o+'" alt="查看目标服务器详情.png"></p></li><li><p>单击<strong>产品/服务</strong>名称，进入<strong>管理产品</strong>详情页面。此页面支持请求取消、开机、关机等操作。关于服务器信息详情介绍和服务器操作可参考各产品或服务的文档。</p><p><img src="'+e+'" alt="管理产品.png"></p></li></ol><hr><h3 id="新开工单" tabindex="-1">新开工单 <a class="header-anchor" href="#新开工单" aria-label="Permalink to &quot;新开工单&quot;">​</a></h3><p>新开工单支持对该产品服务提交问题工单。</p><ol><li><p>在我的产品与服务页面列表右侧，单击<strong>新开工单</strong>，进入<strong>提交工单</strong>页面。</p><p><img src="'+i+'" alt="产品或服务新开工单.png"></p></li><li><p>根据页面提示输入主题、问题描述等信息。 <img src="'+l+'" alt="新开工单11.png"></p></li><li><p>单击提交。</p></li></ol><hr><h3 id="查看账单信息" tabindex="-1">查看账单信息 <a class="header-anchor" href="#查看账单信息" aria-label="Permalink to &quot;查看账单信息&quot;">​</a></h3><p>查看账单信息支持查看该产品/服务的全部账单记录。</p><ol><li><p>在我的产品与服务页面列表右侧，单击<strong>账单信息</strong>，进入<strong>我的账单</strong>页面。此页面支持查看全部、已付款、未付款、已取消、已退款和已过期的账单；支持通过搜索框搜索账单；支持查看购买此产品的不同日期产生的账单。</p><p><img src="'+g+'" alt="产品或服务的账单信息.png"></p></li><li><p>我的账单页面支持查看服务和查看账单。</p><p><img src="'+E+'" alt="新我的帐单.png"></p><p>a.查看服务：支持查看当前帐单对应的服务。 单击<strong>查看服务</strong>，进入我的产品与服务页面。</p><p><img src="'+c+'" alt="查看我的服务详情.png"></p><p>b.查看账单：支持查看当前账单详情。 单击<strong>查看账单</strong>，进入我的帐单页面。此页面支持查看账单详情信息，可根据需要打印和下载账单。</p><p><img src="'+m+'" alt="查看账单详情.png"></p></li></ol><hr><h3 id="提前续费" tabindex="-1">提前续费 <a class="header-anchor" href="#提前续费" aria-label="Permalink to &quot;提前续费&quot;">​</a></h3><p>提前续费是指在当前服务有效期还没结束时，主动为其续费来延长使用时间。</p><blockquote><p><strong>说明</strong></p><p>为保障您的产品/服务正常使用，请留意以下续费及产品/服务状态变更规则：</p><ul><li>产品/服务到期前 10 天，系统将自动生成续费账单，请您及时完成续费操作；</li><li>到期未续费的，产品/服务会在到期后的第 2 天被暂停。 <ul><li>暂停期间完成续费，产品/服务可立即恢复使用；</li><li>若暂停满 4 天仍未续费，产品/服务将被下架。</li></ul></li></ul></blockquote><ol><li><p>在我的产品/服务列表右侧操作列，单击<strong>提前续费</strong>，进入<strong>续费管理</strong>页面。<strong>续费管理</strong>页面支持查看当前付款周期和当前产品到期时间。</p><p><img src="'+A+'" alt="提前续费.png"></p></li><li><p>选择不同的续费周期，续费周期支持选择月付、季付、半年付和年付。单击<strong>结账</strong>。</p></li><li><p>在<strong>我的账单</strong>页面，选择付款方式。若有余额，可以选择使用余额支付。</p><p><img src="'+_+'" alt="付款结算.png"></p></li><li><p>完成付款。</p></li></ol>',21)])])}const k=s(d,[["render",B]]);export{q as __pageData,k as default};
